if(!element)throw Error('R2_STOP_BUTTON_MISSING');
const args={app_ref:ref,target:{type:'element',index:element.index},return_state:'none'};
const pause=ms=>new Promise(done=>setTimeout(done,ms));
const directory=join('{{e2eRuntimeRoot}}','cua-r2','fixture-run');
const config=JSON.parse(await readFile(join('{{e2eRuntimeRoot}}','cua-r2','fault-config.json'),'utf8'));
const pendingFile=join(config.fixtureDirectory,'write-pending.json');
const running=c.left_click(args);let pending;
for(let i=0;i<500;i++){try{const p=JSON.parse(await readFile(pendingFile,'utf8'));if(p.nonce===f.barrierNonce&&p.sequence===f.target.requests+1){pending=p;break;}}catch{}await pause(3);}
if(!pending)throw Error('R2_STOP_PENDING_MISSING');
const stopped=await c.stop_computer_control({reason:'controlled-r2-test'});
